import{at as e,it as t,n,vt as r}from"./chunks/framework.CsjHfu6k.js";var i=JSON.parse(`{"title":"Magisk 更新日志","description":"","frontmatter":{},"headers":[],"relativePath":"changes.md","filePath":"changes.md","lastUpdated":1792939073000}`),a={name:`changes.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="magisk-更新日志" tabindex="-1">Magisk 更新日志 <a class="header-anchor" href="#magisk-更新日志" aria-label="Permalink to “Magisk 更新日志”">​</a></h1><h2 id="v31-1" tabindex="-1">v31.1 <a class="header-anchor" href="#v31-1" aria-label="Permalink to “v31.1”">​</a></h2><ul><li>[General] 支持无头系统用户模式（HSUM）设备</li><li>[General] 放弃对 Android 6.0 的支持；Android 7.0 现在是支持的最低版本</li><li>[General] 移除应用隐藏（重新打包）功能和占位应用；Magisk 不再在应用缺失时自动重新安装</li><li>[App] 移除响应式超级用户请求提示；超级用户访问权限现在在“超级用户”选项卡中提前明确授予</li><li>[App] 统一本地文件和远程 URL 的映像修补流程，涵盖原始映像、OTA zip、出厂映像 zip、三星 Odin tar 和 Aluminium OS recovery GPT 映像</li><li>[App] 自动为 Google Pixel 和 Googlebook（Aluminium OS）设备建议官方固件下载</li><li>[App] 在 Googlebook 上支持修补 Aluminium OS recovery 映像并直接写入已连接的 USB 驱动器</li><li>[App] 在下载和修补映像时显示实时原地读/写进度和传输速度</li><li>[MagiskSU] 移除过时的超级用户访问模式和重新认证设置</li><li>[MagiskSU] 修复 <code>-g</code>/<code>-G</code> 参数处理，将未知选项转发给 shell，并修复守护进程执行信号处理</li><li>[MagiskBoot] 原生支持对 ChromeOS 启动映像签名，并在重新打包时自动重新签名，移除外部 <code>futility</code> 二进制文件</li><li>[MagiskBoot] 使用 ASN.1 DER 编码修复 AVB 1.0 ECDSA 签名验证和签名</li><li>[MagiskBoot] 在启动映像重新打包期间保留三星 <code>SignerVer02</code> 签名</li><li>[MagiskBoot] 撤销重新打包时更新 AVB 哈希描述符映像大小的更改</li><li>[MagiskBoot] 为 XZ 压缩启用架构特定的 BCJ 过滤器，并改进 <code>zImage</code> 压缩载荷检测</li><li>[MagiskBoot] 支持在 Linux 和 macOS 主机上原生构建 <code>magiskboot</code></li><li>[Core] 修复处理 <code>NULL</code> 数据库字符串或守护进程连接失败时的潜在崩溃</li></ul><details class="details custom-block"><summary>英文原版</summary><ul><li>[General] Support Headless System User Mode (HSUM) devices</li><li>[General] Drop support for Android 6.0; Android 7.0 is now the minimum supported version</li><li>[General] Remove the app hiding (repackaging) feature and the stub app; Magisk no longer reinstalls the app automatically if it is missing</li><li>[App] Remove reactive superuser request prompts; superuser access is now explicitly granted ahead of time in the Superuser tab</li><li>[App] Unify the image patching pipeline across local files and remote URLs for raw images, OTA zips, factory image zips, Samsung Odin tars, and Aluminium OS recovery GPT images</li><li>[App] Automatically suggest official firmware downloads for Google Pixel and Googlebook (Aluminium OS) devices</li><li>[App] Support patching Aluminium OS recovery images and writing directly to a connected USB drive on Googlebooks</li><li>[App] Display real-time in-place read/write progress and transfer speeds when downloading and patching images</li><li>[MagiskSU] Remove obsolete superuser access mode and reauthentication settings</li><li>[MagiskSU] Fix <code>-g</code>/<code>-G</code> argument handling, forward unknown options to the shell, and fix daemon exec signal handling</li><li>[MagiskBoot] Support signing ChromeOS boot images natively and automatically re-sign on repack, removing the external <code>futility</code> binary</li><li>[MagiskBoot] Fix AVB 1.0 ECDSA signature verification and signing by using ASN.1 DER encoding</li><li>[MagiskBoot] Preserve Samsung <code>SignerVer02</code> signatures during boot image repack</li><li>[MagiskBoot] Revert updating AVB hash descriptor image size on repack</li><li>[MagiskBoot] Enable architecture-specific BCJ filters for XZ compression and improve <code>zImage</code> compressed payload detection</li><li>[MagiskBoot] Support building <code>magiskboot</code> natively on Linux and macOS hosts</li><li>[Core] Fix potential crashes when handling <code>NULL</code> database strings or failed daemon connections</li></ul></details><h2 id="v31-0" tabindex="-1">v31.0 <a class="header-anchor" href="#v31-0" aria-label="Permalink to “v31.0”">​</a></h2><ul><li>[App] 使用 Jetpack Compose 和 Material 3 彻底重做 UI，完全移除旧版 View 和 Fragment 架构</li><li>[App] 添加新的内置终端模拟器，支持完整 TTY 和 ANSI，可用于模块刷写和操作脚本</li><li>[App] 支持直接从远程 OTA URL 下载并流式提取启动映像</li><li>[MagiskBoot] 支持动态 zImage 载荷大小，重新打包时无需精确大小填充</li><li>[MagiskBoot] 更新 AVB 哈希描述符映像大小，使其与解包后的映像大小匹配</li><li>[MagiskBoot] 降低 XZ 和 LZMA 的默认压缩预设，以减少重新打包时的内存占用</li><li>[Zygisk] 支持 Android 17（API 37）</li><li>[Zygisk] 支持 Meta Quest（Horizon OS）的 lazy partition zygotes</li><li>[MagiskPolicy] 修复包含连字符的名称的标识符解析</li><li>[resetprop] 添加 <code>--compact</code>（<code>-c</code>）标志以压缩属性存储区域</li><li>[MagiskInit] 正确优先于 <code>force_normal_boot</code> 检测充电模式</li><li>[DenyList] 将 <code>webview_zygote</code> 添加为卸载目标</li></ul><details class="details custom-block"><summary>英文原版</summary><ul><li>[App] Complete UI overhaul with Jetpack Compose and Material 3, completely removing the legacy View and Fragment architecture</li><li>[App] Add new built-in terminal emulator with full TTY and ANSI support for module flashing and action scripts</li><li>[App] Support downloading and streaming boot image extraction directly from remote OTA URLs</li><li>[MagiskBoot] Support dynamic zImage payload sizes without requiring exact size padding during repack</li><li>[MagiskBoot] Update AVB hash descriptor image size to match unpacked image size</li><li>[MagiskBoot] Lower default compression preset for XZ and LZMA to reduce memory usage during repacking</li><li>[Zygisk] Support Android 17 (API 37)</li><li>[Zygisk] Support Meta Quest (Horizon OS) lazy partition zygotes</li><li>[MagiskPolicy] Fix identifier parsing for names containing hyphens</li><li>[resetprop] Add <code>--compact</code> (<code>-c</code>) flag to compact property storage areas</li><li>[MagiskInit] Properly prioritize charger mode detection before <code>force_normal_boot</code></li><li>[DenyList] Add <code>webview_zygote</code> as an unmount target</li></ul></details><h2 id="v30-7" tabindex="-1">v30.7 <a class="header-anchor" href="#v30-7" aria-label="Permalink to “v30.7”">​</a></h2><ul><li>[MagiskInit] 支持 Android 16 QPR2 sepolicy 格式</li><li>[MagiskInit] 支持将 klogdump 分区用作预初始化存储</li><li>[Zygisk] 支持 Android 16 QPR2 及更高版本</li><li>[Zygisk] 支持 Android XR 和部分努比亚设备</li><li>[MagiskSU] 默认不丢弃能力，即使切换到非 root UID。请显式使用 <code>--drop-cap</code> 参数来丢弃能力。</li><li>[MagiskBoot] 更好的 lzma 格式检测</li><li>[MagiskBoot] 修复各种命令行参数解析错误</li></ul><details class="details custom-block"><summary>英文原版</summary><ul><li>[MagiskInit] Support Android 16 QPR2 sepolicy format</li><li>[MagiskInit] Support using klogdump partition as pre-init storage</li><li>[Zygisk] Support Android 16 QPR2 and higher</li><li>[Zygisk] Support Android XR and some Nubia devices</li><li>[MagiskSU] Do not drop capabilities by default, even when switching to non-root UIDs. Explicitly use the <code>--drop-cap</code> argument to drop capabilities.</li><li>[MagiskBoot] Better lzma format detection</li><li>[MagiskBoot] Fix various commandline argument parsing bugs</li></ul></details><h2 id="v30-6" tabindex="-1">v30.6 <a class="header-anchor" href="#v30-6" aria-label="Permalink to “v30.6”">​</a></h2><ul><li>[MagiskInit] 回退了一个可能导致启动循环的更改</li></ul><details class="details custom-block"><summary>英文原版</summary><ul><li>[MagiskInit] Revert a change that could result in bootloops</li></ul></details><h2 id="v30-5" tabindex="-1">v30.5 <a class="header-anchor" href="#v30-5" aria-label="Permalink to “v30.5”">​</a></h2><ul><li>[General] 将相当一部分代码库迁移到 Rust</li><li>[General] 各种小错误修复</li><li>[General] 支持将 Magisk 安装到 vendor_boot 分区</li><li>[Core] 改进 Magisk 特定文件的注入逻辑</li><li>[MagiskSU] 添加即使在以 root（uid=0）运行时也能限制 Linux 能力的功能</li><li>[MagiskSU] 当内核不支持零用户空间复制 API 时回退到旧实现</li><li>[MagiskPolicy] 支持 Android 16 QPR2 中引入的新 sepolicy 二进制格式</li><li>[resetprop] 减少属性修改痕迹</li><li>[resetprop] 正确支持具有属性覆盖的 Android 版本</li></ul><details class="details custom-block"><summary>英文原版</summary><ul><li>[General] Migrate a significant portion of the codebase to Rust</li><li>[General] Various minor bug fixes</li><li>[General] Support installing Magisk into vendor_boot partition</li><li>[Core] Improve Magisk specific files injection logic</li><li>[MagiskSU] Add ability to restrict Linux capabilities even if running as root (uid=0)</li><li>[MagiskSU] Fallback to older implementation when the kernel doesn&#39;t support zero userspace copy APIs</li><li>[MagiskPolicy] Support new sepolicy binary format introduced in Android 16 QPR2</li><li>[resetprop] Reduce property modification traces</li><li>[resetprop] Properly support Android versions with property overrides</li></ul></details><h2 id="v30-4" tabindex="-1">v30.4 <a class="header-anchor" href="#v30-4" aria-label="Permalink to “v30.4”">​</a></h2><ul><li>[MagiskSU] 修复若干实现错误</li></ul><details class="details custom-block"><summary>英文原版</summary><ul><li>[MagiskSU] Fix several implementation bugs</li></ul></details><h2 id="v30-3" tabindex="-1">v30.3 <a class="header-anchor" href="#v30-3" aria-label="Permalink to “v30.3”">​</a></h2><ul><li>[General] 支持将 Magisk 安装到 vendor_boot 分区</li><li>[MagiskPolicy] 支持 Android 16 QPR2 中引入的新 sepolicy 二进制格式</li><li>[Core] 将更多代码迁移到 Rust</li><li>[MagiskSU] 当内核不支持零用户空间复制 API 时回退到旧实现</li></ul><details class="details custom-block"><summary>英文原版</summary><ul><li>[General] Support installing Magisk into vendor_boot partition</li><li>[MagiskPolicy] Support new sepolicy binary format introduced in Android 16 QPR2</li><li>[Core] Migrate much more code into Rust</li><li>[MagiskSU] Fallback to older implementation when the kernel doesn&#39;t support zero userspace copy APIs</li></ul></details><h2 id="v30-2" tabindex="-1">v30.2 <a class="header-anchor" href="#v30-2" aria-label="Permalink to “v30.2”">​</a></h2><ul><li>[Core] 修复涉及 overlayfs 时破坏模块的边缘情况</li><li>[Core] 修复某些情况下的模块 <code>.replace</code> 功能</li><li>[resetprop] 减少属性修改痕迹</li></ul><details class="details custom-block"><summary>英文原版</summary><ul><li>[Core] Fix an edge case breaking modules when overlayfs is involved</li><li>[Core] Fix module <code>.replace</code> functionality in certain situations</li><li>[resetprop] Reduce property modification traces</li></ul></details><h2 id="v30-1" tabindex="-1">v30.1 <a class="header-anchor" href="#v30-1" aria-label="Permalink to “v30.1”">​</a></h2><ul><li>[Core] 修复模块挂载实现中的错误</li><li>[MagiskSU] 添加即使在以 root（uid=0）运行时也能限制 Linux 能力的功能</li></ul><details class="details custom-block"><summary>英文原版</summary><ul><li>[Core] Fix bug in module mounting implementation</li><li>[MagiskSU] Add ability to restrict Linux capabilities even if running as root (uid=0)</li></ul></details><h2 id="v30-0" tabindex="-1">v30.0 <a class="header-anchor" href="#v30-0" aria-label="Permalink to “v30.0”">​</a></h2><ul><li>[General] 各种小错误修复</li><li>[Core] 将模块实现迁移到 Rust</li><li>[Core] 改进 Magisk 特定文件的注入逻辑</li><li>[MagiskBoot] 将压缩代码迁移到 Rust</li></ul><details class="details custom-block"><summary>英文原版</summary><ul><li>[General] Various minor bug fixes</li><li>[Core] Migrate module implementation to Rust</li><li>[Core] Improve Magisk specific files injection logic</li><li>[MagiskBoot] Migrate compression code to Rust</li></ul></details><h2 id="v29-0" tabindex="-1">v29.0 <a class="header-anchor" href="#v29-0" aria-label="Permalink to “v29.0”">​</a></h2><ul><li>[General] 大规模内部重构和代码迁移</li><li>[App] 支持下载使用 XZ 压缩的模块 zip 文件</li><li>[App] 当系统动画被禁用时禁用应用动画</li><li>[MagiskMount] 支持使用空白文件节点，通过模块以 systemless 方式删除文件</li><li>[MagiskInit] 重新设计 sepolicy 修补和注入逻辑</li><li>[MagiskSU] 更好的 TTY/PTY 支持</li></ul><details class="details custom-block"><summary>英文原版</summary><ul><li>[General] Massive internal refactoring and code migration</li><li>[App] Support downloading module zip files with XZ compression</li><li>[App] Disable app animations when system animations are disabled</li><li>[MagiskMount] Support systemlessly deleting files with modules using blank file nodes</li><li>[MagiskInit] Redesign sepolicy patching and injection logic</li><li>[MagiskSU] Better TTY/PTY support</li></ul></details><h2 id="v28-1" tabindex="-1">v28.1 <a class="header-anchor" href="#v28-1" aria-label="Permalink to “v28.1”">​</a></h2><ul><li>[App] 修复占位 APK 下载链接</li><li>[App] 修复对低于 Android 8.0 的支持</li><li>[General] 修复对 MTK 三星设备的支持</li><li>[MagiskInit] 修复 2SI 设备的回归问题</li><li>[MagiskPolicy] 修复导致 <code>overlay.d</code> 替换文件无法访问的回归问题</li></ul><details class="details custom-block"><summary>英文原版</summary><ul><li>[App] Fix stub APK download link</li><li>[App] Fix support for Android lower than 8.0</li><li>[General] Fix support for MTK Samsung devices</li><li>[MagiskInit] Fix a regression for 2SI devices</li><li>[MagiskPolicy] Fix a regression causing <code>overlay.d</code> replaced files to be not accessible</li></ul></details><h2 id="v28-0" tabindex="-1">v28.0 <a class="header-anchor" href="#v28-0" aria-label="Permalink to “v28.0”">​</a></h2><ul><li>[General] 支持 16K 页面大小</li><li>[General] 添加对 RISC-V 的基本支持（发布版本中未构建）</li><li>[General] 使用精简 libc 构建静态可执行文件（<code>magiskinit</code> 和 <code>magiskboot</code>），以减小体积</li><li>[Core] 移除 magic mount 不需要的镜像</li><li>[Core] 更新启动映像检测逻辑，以支持更多设备</li><li>[MagiskInit] 重写将 <code>magiskinit</code> 作为 <code>init</code> 注入的 2SI 逻辑</li><li>[MagiskInit] 更新预初始化分区检测</li><li>[Zygisk] 更新内部 JNI 挂钩实现</li><li>[MagiskPolicy] 修补后保留 sepolicy 配置标志</li><li>[MagiskPolicy] 优化修补规则，减少注入的新规则数量</li><li>[DenyList] 支持在禁用 Zygisk 时仍强制执行拒绝列表</li><li>[Resetprop] 改进实现，以绕过若干属性修改检测</li><li>[Resetprop] 更新以正确处理属性覆盖（property overlays）</li><li>[App] 大规模内部代码重构</li><li>[App] 支持修补大于 8GiB 的三星固件映像</li><li>[App] 在 Android 14 上使用用户发起的作业代替前台服务</li><li>[App] 支持 Android 13+ 内置的按应用语言偏好设置</li><li>[App] 添加 <code>action.sh</code> 支持，允许模块定义从 UI 触发的操作</li><li>[MagiskBoot] 支持在不进行解压缩的情况下拆分内核映像</li><li>[MagiskBoot] 正确支持 vendor boot 映像</li><li>[MagiskBoot] 从内核映像中禁用三星 PROCA</li></ul><details class="details custom-block"><summary>英文原版</summary><ul><li>[General] Support 16k page size</li><li>[General] Add basic support for RISC-V (not built in releases)</li><li>[General] Use a minimal libc to build static executables (<code>magiskinit</code> and <code>magiskboot</code>) for smaller sizes</li><li>[Core] Remove unnecessary mirror for magic mount</li><li>[Core] Update boot image detection logic to support more devices</li><li>[MagiskInit] Rewrite 2SI logic for injecting <code>magiskinit</code> as <code>init</code></li><li>[MagiskInit] Update preinit partition detection</li><li>[Zygisk] Update internal JNI hooking implementation</li><li>[MagiskPolicy] Preserve sepolicy config flag after patching</li><li>[MagiskPolicy] Optimize patching rules to reduce the amount of new rules being injected</li><li>[DenyList] Support enforcing denylist when Zygisk is disabled</li><li>[Resetprop] Improve implementation to workaround several property modification detections</li><li>[Resetprop] Update to properly work with property overlays</li><li>[App] Major internal code refactoring</li><li>[App] Support patching Samsung firmware with images larger than 8GiB</li><li>[App] Use user-initiated job instead of foreground services on Android 14</li><li>[App] Support Android 13+ built-in per-app language preferences</li><li>[App] Add <code>action.sh</code> support to allow modules to define an action triggered from UI</li><li>[MagiskBoot] Support spliting kernel images without decompression</li><li>[MagiskBoot] Properly support vendor boot images</li><li>[MagiskBoot] Disable Samsung PROCA from kernel image</li></ul></details><h2 id="v27-0" tabindex="-1">v27.0 <a class="header-anchor" href="#v27-0" aria-label="Permalink to “v27.0”">​</a></h2><ul><li>[Zygisk] 引入新的代码注入机制</li><li>[Zygisk] 支持在 U QPR2 中引入的新签名</li><li>[SEPolicy] 更新 libsepol 以正确设置某些策略配置位</li><li>[MagiskBoot] 支持压缩 <code>init</code>，以便在具有较小启动分区的设备上安装Magisk</li><li>[ResetProp] 添加新的等待属性功能 <code>resetprop -w</code></li></ul><details class="details custom-block"><summary>英文原版</summary><ul><li>[Zygisk] Introduce new code injection mechanism</li><li>[Zygisk] Support new signature introduced in U QPR2</li><li>[SEPolicy] Update libsepol to properly set some policy config bits</li><li>[MagiskBoot] Support compressing <code>init</code> so Magisk is installable on devices with small boot partitions</li><li>[ResetProp] Add new wait for property feature <code>resetprop -w</code></li></ul></details><h2 id="v26-4" tabindex="-1">v26.4 <a class="header-anchor" href="#v26-4" aria-label="Permalink to “v26.4”">​</a></h2><ul><li>[MagiskBoot] 如果签名启动镜像较大，则不要填充零</li><li>[MagiskPolicy] 修复 <code>genfscon</code> 和 <code>filename_trans</code></li><li>[MagiskPolicy] 修复了 <code>libsepol</code> 中的错误</li><li>[Zygisk] 修复并简化文件描述符净化逻辑</li><li>[应用] 修补 AP tar 文件时防止 OOM</li><li>[应用] 修复设备配置检测中的错误</li><li>[Daemon] 修复 APK 的证书解析问题</li><li>[常规] 修复了忽略 C++ 代码中的日志记录错误</li></ul><details class="details custom-block"><summary>英文原版</summary><ul><li>[MagiskBoot] Don&#39;t pad zeros if signed boot image is larger</li><li>[MagiskPolicy] Fix <code>genfscon</code> and <code>filename_trans</code></li><li>[MagiskPolicy] Fix bug in <code>libsepol</code></li><li>[Zygisk] Fix and simplify file descriptor sanitization logic</li><li>[App] Prevent OOM when patching AP tarfiles</li><li>[App] Fix bug in device configuration detection</li><li>[Daemon] Fix certificate parsing of APKs</li><li>[General] Fix logging errors from C++ code being ignored</li></ul></details><h2 id="v26-3" tabindex="-1">v26.3 <a class="header-anchor" href="#v26-3" aria-label="Permalink to “v26.3”">​</a></h2><ul><li>[常规] 修复设备信息检测脚本</li><li>[常规] 将 BusyBox 更新到 1.36.1</li><li>[常规] 更新工具链，生成损坏的 arm32 可执行文件</li><li>[应用] 修复根服务无法绑定一加设备的问题</li></ul><details class="details custom-block"><summary>英文原版</summary><ul><li>[General] Fix device information detection script</li><li>[General] Update BusyBox to 1.36.1</li><li>[General] Update toolchain that produces broken arm32 executables</li><li>[App] Fix root service unable to bind on OnePlus devices</li></ul></details><h2 id="v26-2" tabindex="-1">v26.2 <a class="header-anchor" href="#v26-2" aria-label="Permalink to “v26.2”">​</a></h2><ul><li>[MagiskBoot] 支持从<code>payload.bin</code>中提取启动映像</li><li>[MagiskBoot] 支持包含字符文件的 cpio 文件</li><li>[MagiskBoot] 支持列出 cpio 内容</li><li>[MagiskBoot] 直接处理 AVB 1.0 签名和验证，无需通过 Java 实现</li><li>[守护进程] 使守护程序套接字成为 MAGISKTMP 中的固定路径</li><li>[resetprop] 支持打印属性上下文</li><li>[resetprop] 仅支持从存储中打印持久属性</li><li>[resetprop] 正确支持设置持久属性绕过 property_service</li><li>[MagiskSU] 支持 <code>-g</code> 和 <code>-G</code> 选项</li><li>[MagiskSU] 支持使用 <code>-t</code> 将挂载命名空间切换到 PID</li><li>[MagiskPolicy] 修复修补扩展权限</li><li>[MagiskPolicy] 支持更多语法以获得扩展权限</li><li>[MagiskPolicy] 支持打印加载的 sepolicy 规则</li><li>[应用程序] 支持从 ROM 压缩包修补启动映像</li><li>[应用程序] 使用 <code>init_boot.img</code> 修补三星固件时正确保留 <code>boot.img</code></li></ul><details class="details custom-block"><summary>英文原版</summary><ul><li>[MagiskBoot] Support extracting boot image from <code>payload.bin</code></li><li>[MagiskBoot] Support cpio files containing character files</li><li>[MagiskBoot] Support listing cpio content</li><li>[MagiskBoot] Directly handle AVB 1.0 signing and verification without going through Java implementation</li><li>[Daemon] Make daemon socket a fixed path in MAGISKTMP</li><li>[resetprop] Support printing property context</li><li>[resetprop] Support only printing persistent properties from storage</li><li>[resetprop] Properly support setting persistent properties bypassing property_service</li><li>[MagiskSU] Support <code>-g</code> and <code>-G</code> options</li><li>[MagiskSU] Support switching mount namespace to PID with <code>-t</code></li><li>[MagiskPolicy] Fix patching extended permissions</li><li>[MagiskPolicy] Support more syntax for extended permissions</li><li>[MagiskPolicy] Support printing out the loaded sepolicy rules</li><li>[App] Support patching boot image from ROM zips</li><li>[App] Properly preserve <code>boot.img</code> when patching Samsung firmware with <code>init_boot.img</code></li></ul></details><h2 id="v26-1" tabindex="-1">v26.1 <a class="header-anchor" href="#v26-1" aria-label="Permalink to “v26.1”">​</a></h2><ul><li>[应用程序] 修复了撤销根权限时崩溃的问题</li><li>[MagiskInit] 在选择预初始化分区时，始终更喜欢 <code>ext4</code> 分区而不是 <code>f2fs</code></li><li>[常规] 从镜像恢复模块文件的上下文/所有者/组。这是 v26.0 中引入的回归</li></ul><details class="details custom-block"><summary>英文原版</summary><ul><li>[App] Fix crashing when revoking root permissions</li><li>[MagiskInit] Always prefer <code>ext4</code> partitions over <code>f2fs</code> when selecting the pre-init partition</li><li>[General] Restore module files&#39; context/owner/group from mirror. This is a regression introduced in v26.0</li></ul></details><h2 id="v26-0" tabindex="-1">v26.0 <a class="header-anchor" href="#v26-0" aria-label="Permalink to “v26.0”">​</a></h2><ul><li>[General] Bump minimum supported Android version to Android 6.0</li><li>[General] New magic mount backend. It supports loading modules into system with <code>overlayfs</code> files injected</li><li>[Zygisk] Release new API version 4</li><li>[Zygisk] Prevent crashing daemon in error</li><li>[Zygisk] Rewrite zygote code injection with new loader library approach</li><li>[Zygisk] Rewrite code unloading implementation</li><li>[MagiskBoot] Support amonet microloader devices</li><li>[MagiskBoot] Always use lz4_legacy compression on v4 boot images. This fixes boot image patching issues on Android U preview.</li><li>[MagiskInit] Support replacing existing *.rc files in <code>overlay.d</code></li><li>[MagiskInit] Rewrite sepolicy.rules mounting and loading implementation</li><li>[App] Make stub patching 100% offline</li><li>[App] Support patching <code>init_boot.img</code> for Samsung ODIN firmware</li><li>[MagiskPolicy] Fix minor bug in command line argument parsing</li><li>[MagiskPolicy] Update rules to support Android U</li></ul><h2 id="v25-2" tabindex="-1">v25.2 <a class="header-anchor" href="#v25-2" aria-label="Permalink to “v25.2”">​</a></h2><ul><li>[MagiskInit] Fix a potential issue when stub cpio is used</li><li>[MagiskInit] Fix reboot to recovery when stub cpio is used</li><li>[MagiskInit] Fix sepolicy.rules symlink for rootfs devices</li><li>[General] Better data encryption detection</li><li>[General] Move the whole logging infrastructure into Rust</li></ul><h2 id="v25-1" tabindex="-1">v25.1 <a class="header-anchor" href="#v25-1" aria-label="Permalink to “v25.1”">​</a></h2><ul><li>[MagiskBoot] Fix ramdisk backup being incorrectly skipped</li><li>[MagiskBoot] Add new feature to detect unsupported dtb and abort during installation</li><li>[Zygisk] Change binary hijack paths</li><li>[App] Fix incorrect recovery mode detection and installation</li><li>[MagiskInit] Fix config not properly exported in legacy SAR devices</li><li>[General] Enforce the Magisk app to always match or be newer than <code>magiskd</code></li></ul><h2 id="v25-0" tabindex="-1">v25.0 <a class="header-anchor" href="#v25-0" aria-label="Permalink to “v25.0”">​</a></h2><ul><li>[MagiskInit] Update 2SI implementation, significantly increase device compatibility (e.g. Sony Xperia devices)</li><li>[MagiskInit] Introduce new <code>sepolicy</code> injection mechanism</li><li>[MagiskInit] Support Oculus Go</li><li>[MagiskInit] Support Android 13 GKIs (Pixel 6)</li><li>[MagiskBoot] Fix vbmeta extraction implementation</li><li>[App] Fix stub app on older Android versions</li><li>[App] [MagiskSU] Properly support apps using <code>sharedUserId</code></li><li>[MagiskSU] Fix a possible crash in <code>magiskd</code></li><li>[MagiskSU] Prune unused UIDs as soon as <code>system_server</code> restarts to prevent UID reuse attacks</li><li>[MagiskSU] Verify and enforce the installed Magisk app&#39;s certificate to match the distributor&#39;s signature</li><li>[MagiskSU] [Zygisk] Proper package management and detection</li><li>[Zygisk] Fix function hooking on devices running Android 12 with old kernels</li><li>[Zygisk] Fix Zygisk&#39;s self code unloading implementation</li><li>[DenyList] Fix DenyList on shared UID apps</li><li>[BusyBox] Add workaround for devices running old kernels</li></ul><h2 id="v24-3" tabindex="-1">v24.3 <a class="header-anchor" href="#v24-3" aria-label="Permalink to “v24.3”">​</a></h2><ul><li>[General] Stop using <code>getrandom</code> syscall</li><li>[Zygisk] Update API to v3, adding new fields to <code>AppSpecializeArgs</code></li><li>[App] Improve app repackaging installation workflow</li></ul><h2 id="v24-2" tabindex="-1">v24.2 <a class="header-anchor" href="#v24-2" aria-label="Permalink to “v24.2”">​</a></h2><ul><li>[MagiskSU] Fix buffer overflow</li><li>[MagiskSU] Fix owner managed multiuser superuser settings</li><li>[MagiskSU] Fix command logging when using <code>su -c &lt;cmd&gt;</code></li><li>[MagiskSU] Prevent su request indefinite blocking</li><li>[MagiskBoot] Support <code>lz4_legacy</code> archive with multiple magic</li><li>[MagiskBoot] Fix <code>lz4_lg</code> compression</li><li>[DenyList] Allow targeting processes running as system UID</li><li>[Zygisk] Workaround Samsung&#39;s &quot;early zygote&quot;</li><li>[Zygisk] Improved Zygisk loading mechanism</li><li>[Zygisk] Fix application UID tracking</li><li>[Zygisk] Fix improper <code>umask</code> being set in zygote</li><li>[App] Fix BusyBox execution test</li><li>[App] Improve stub loading mechanism</li><li>[App] Major app upgrade flow improvements</li><li>[General] Improve commandline error handling and messaging</li></ul><h2 id="v24-1" tabindex="-1">v24.1 <a class="header-anchor" href="#v24-1" aria-label="Permalink to “v24.1”">​</a></h2><ul><li>[App] Stability improvements</li></ul><h2 id="v24-0" tabindex="-1">v24.0 <a class="header-anchor" href="#v24-0" aria-label="Permalink to “v24.0”">​</a></h2><ul><li>[General] MagiskHide is removed from Magisk</li><li>[General] Support Android 12</li><li>[General] Support devices that do not support 32-bit and only runs 64-bit code</li><li>[General] Update BusyBox to 1.34.1</li><li>[Zygisk] Introduce new feature: Zygisk</li><li>[Zygisk] Introduce DenyList feature to revert Magisk features in user selected processes</li><li>[MagiskBoot] Support patching 32-bit kernel zImages</li><li>[MagiskBoot] Support boot image header v4</li><li>[MagiskBoot] Support patching out <code>skip_initramfs</code> from dtb bootargs</li><li>[MagiskBoot] Add new env variable <code>PATCHVBMETAFLAG</code> to configure whether vbmeta flags should be patched</li><li>[MagiskInit] Support loading fstab from <code>/system/etc</code> (required for Pixel 6)</li><li>[MagiskInit] Support <code>/proc/bootconfig</code> for loading boot configurations</li><li>[MagiskInit] Better support for some Meizu devices</li><li>[MagiskInit] Better support for some OnePlus/Oppo/Realme devices</li><li>[MagiskInit] Support <code>init.real</code> on some Sony devices</li><li>[MagiskInit] Skip loading Magisk when detecting DSU</li><li>[MagiskPolicy] Load <code>*_compat_cil_file</code> from system_ext</li><li>[MagiskSU] Use isolated devpts if the kernel supports it</li><li>[MagiskSU] Fix root shell if isolated mount namespace is set</li><li>[resetprop] Deleted properties are now wiped from memory instead of just unlinking</li><li>[App] Build a single APK for all ABIs</li><li>[App] Switch to use standard bottom navigation bar</li><li>[App] Downloading modules from the centralized Magisk-Modules-Repo is removed</li><li>[App] Support user configuration of boot image vbmeta patching</li><li>[App] Restore the ability to install Magisk on the other slot on some A/B devices</li><li>[App] Allow modules to specify an update URL for in-app update + install</li></ul><h2 id="v23-0" tabindex="-1">v23.0 <a class="header-anchor" href="#v23-0" aria-label="Permalink to “v23.0”">​</a></h2><ul><li>[App] Update snet extension. This fixes SafetyNet API errors.</li><li>[App] Fix a bug in the stub app that causes APK installation to fail</li><li>[App] Hide annoying errors in logs when hidden as stub</li><li>[App] Fix issues when patching ODIN tar files when the app is hidden</li><li>[General] Remove all pre Android 5.0 support</li><li>[General] Update BusyBox to use proper libc</li><li>[General] Fix C++ undefined behaviors</li><li>[General] Several <code>sepolicy.rule</code> copy/installation fixes</li><li>[MagiskPolicy] Remove unnecessary sepolicy rules</li><li>[MagiskHide] Update package and process name validation logic</li><li>[MagiskHide] Some changes that prevents zygote deadlock</li></ul><h2 id="v22-1" tabindex="-1">v22.1 <a class="header-anchor" href="#v22-1" aria-label="Permalink to “v22.1”">​</a></h2><ul><li>[App] Prevent multiple installation sessions running in parallel</li><li>[App] Prevent OutOfMemory crashes when checking boot signature on PXA boot images</li><li>[General] Proper cgroup migration implementation</li><li>[General] Rewrite log writer from scratch, should resolve any crashes and deadlocks</li><li>[General] Many scripts updates fixing regressions</li><li>[MagiskHide] Prevent possible deadlock when signal arrives</li><li>[MagiskHide] Partial match process names if necessary</li><li>[MagiskBoot] Preserve and patch AVB 2.0 structures/headers in boot images</li><li>[MagiskBoot] Properly strip out data encryption flags</li><li>[MagiskBoot] Prevent possible integer overflow</li><li>[MagiskInit] Fix <code>sepolicy.rule</code> mounting strategy</li><li>[resetprop] Always delete existing <code>ro.</code> props before updating. This will fix bootloops that could be caused by modifying device fingerprint properties.</li></ul><h2 id="v22-0" tabindex="-1">v22.0 <a class="header-anchor" href="#v22-0" aria-label="Permalink to “v22.0”">​</a></h2><ul><li>[General] Magisk and Magisk Manager is now merged into the same package!</li><li>[App] The term &quot;Magisk Manager&quot; is no longer used elsewhere. We refer it as the Magisk app.</li><li>[App] Support hiding the Magisk app with advanced technique (stub APK loading) on Android 5.0+ (it used to be 9.0+)</li><li>[App] Disallow re-packaging the Magisk app on devices lower than Android 5.0</li><li>[App] Detect and warn about multiple invalid states and provide instructions on how to resolve it</li><li>[MagiskHide] Fix a bug when stopping MagiskHide does not take effect</li><li>[MagiskBoot] Fix bug when unpacking <code>lz4_lg</code> compressed boot images</li><li>[MagiskInit] Support Galaxy S21 series</li><li>[MagiskSU] Fix incorrect APEX paths that caused <code>libsqlite.so</code> fail to load</li></ul><h2 id="v21-4" tabindex="-1">v21.4 <a class="header-anchor" href="#v21-4" aria-label="Permalink to “v21.4”">​</a></h2><ul><li>[MagiskSU] Fix <code>su -c</code> behavior that broke many root apps</li><li>[General] Properly handle read/write over sockets (the <code>broken pipe</code> issue)</li></ul><h2 id="v21-3" tabindex="-1">v21.3 <a class="header-anchor" href="#v21-3" aria-label="Permalink to “v21.3”">​</a></h2><ul><li>[MagiskInit] Avoid mounting <code>f2fs</code> userdata as it may result in kernel crashes. This shall fix a lot of bootloops</li><li>[MagiskBoot] Fix a minor header checksum bug for <code>DHTB</code> header and ASUS <code>blob</code> image formats</li><li>[MagiskHide] Allowing hiding isolated processes if the mount namespace is separated</li></ul><h2 id="v21-2" tabindex="-1">v21.2 <a class="header-anchor" href="#v21-2" aria-label="Permalink to “v21.2”">​</a></h2><ul><li>[MagiskInit] Detect 2SI after mounting <code>system_root</code> on legacy SAR devices</li><li>[General] Make sure <code>post-fs-data</code> scripts cannot block more than 35 seconds</li><li>[General] Fix the <code>magisk --install-module</code> command</li><li>[General] Trim Windows newline when reading files</li><li>[General] Directly log to file to prevent <code>logcat</code> weirdness</li><li>[MagiskBoot] Fix header dump/load for header v3 images</li></ul><h2 id="v21-1" tabindex="-1">v21.1 <a class="header-anchor" href="#v21-1" aria-label="Permalink to “v21.1”">​</a></h2><ul><li>[MagiskBoot] Support boot header v3 (Pixel 5 and 4a 5G)</li><li>[MagiskBoot] Distinguish <code>lz4_lg</code> and <code>lz4_legacy</code> (Pixel 5 and 4a 5G)</li><li>[MagiskBoot] Support vendor boot images (for dev, not relevant for Magisk installation)</li><li>[MagiskInit] Support kernel cmdline <code>androidboot.fstab_suffix</code></li><li>[MagiskInit] Support kernel initialized dm-verity on legacy SAR</li><li>[General] Significantly broaden sepolicy.rule compatibility</li><li>[General] Add Magisk binaries to <code>PATH</code> when executing boot scripts</li><li>[General] Update <code>--remove-modules</code> command implementation</li><li>[General] Make Magisk properly survive after factory reset on Android 11</li><li>[MagiskSU] Add APEX package <code>com.android.i18n</code> to <code>LD_LIBRARY_PATH</code> when linking <code>libsqlite.so</code></li><li>[MagiskHide] Support hiding apps installed in secondary users (e.g. work profile)</li><li>[MagiskHide] Make zygote detection more robust</li></ul><h2 id="v21-0" tabindex="-1">v21.0 <a class="header-anchor" href="#v21-0" aria-label="Permalink to “v21.0”">​</a></h2><ul><li>[General] Support Android 11 🎉</li><li>[General] Add Safe Mode detection. Disable all modules when the device is booting into Safe Mode.</li><li>[General] Increase <code>post-fs-data</code> mode timeout from 10 seconds to 40 seconds</li><li>[MagiskInit] Rewritten 2SI support from scratch</li><li>[MagiskInit] Support when no <code>/sbin</code> folder exists (Android 11)</li><li>[MagiskInit] Dump fstab from device-tree to rootfs and force <code>init</code> to use it for 2SI devices</li><li>[MagiskInit] Strip out AVB for 2SI as it may cause bootloop</li><li>[Modules] Rewritten module mounting logic from scratch</li><li>[MagiskSU] For Android 8.0+, a completely new policy setup is used. This reduces compromises in Android&#39;s sandbox, providing more policy isolation and better security for root users.</li><li>[MagiskSU] Isolated mount namespace will now first inherit from parent process, then isolate itself from the world</li><li>[MagiskSU] Update communication protocol with Magisk Manager to work with the hardened SELinux setup</li><li>[MagiskPolicy] Optimize match all rules. This will significantly reduce policy binary size and save memory and improve general kernel performance.</li><li>[MagiskPolicy] Support declaring new types and attributes</li><li>[MagiskPolicy] Make policy statement closer to stock <code>*.te</code> format. Please check updated documentation or <code>magiskpolicy --help</code> for more details.</li><li>[MagiskBoot] Support compressed <code>extra</code> blobs</li><li>[MagiskBoot] Pad boot images to original size with zeros</li><li>[MagiskHide] Manipulate additional vendor properties</li></ul><h2 id="v20-4" tabindex="-1">v20.4 <a class="header-anchor" href="#v20-4" aria-label="Permalink to “v20.4”">​</a></h2><ul><li>[MagiskInit] Fix potential bootloop in A-only 2SI devices</li><li>[MagiskInit] Properly support Tegra partition naming</li><li>[General] Load libsqlite.so dynamically, which removes the need to use wrapper scripts on Android 10+</li><li>[General] Detect API level with a fallback method on some devices</li><li>[General] Workaround possible bug in x86 kernel readlinkat system call</li><li>[BusyBox] Enable SELinux features. Add chcon/runcon etc., and &#39;-Z&#39; option to many applets</li><li>[BusyBox] Introduce standalone mode. More details in release notes</li><li>[MagiskHide] Disable MagiskHide by default</li><li>[MagiskHide] Add more potential detectable system properties</li><li>[MagiskHide] Add workaround for Xiaomi devices bootloop when MagiskHide is enabled on cross region ROMs</li><li>[MagiskBoot] Support patching special Motorolla DTB format</li><li>[MagiskPolicy] Support &#39;genfscon&#39; sepolicy rules</li><li>[Scripts] Support NAND based boot images (character nodes in /dev/block)</li><li>[Scripts] Better addon.d (both v1 and v2) support</li><li>[Scripts] Support Lineage Recovery for Android 10+</li></ul><h2 id="v20-3" tabindex="-1">v20.3 <a class="header-anchor" href="#v20-3" aria-label="Permalink to “v20.3”">​</a></h2><ul><li>[MagiskBoot] Fix <code>lz4_legacy</code> decompression</li></ul><h2 id="v20-2" tabindex="-1">v20.2 <a class="header-anchor" href="#v20-2" aria-label="Permalink to “v20.2”">​</a></h2><ul><li>[MagiskSU] Properly handle communication between daemon and application (root request prompt)</li><li>[MagiskInit] Fix logging in kmsg</li><li>[MagiskBoot] Support patching dtb/dtbo partition formats</li><li>[General] Support pre-init sepolicy patch in modules</li><li>[Scripts] Update magisk stock image backup format</li></ul><h2 id="v20-1" tabindex="-1">v20.1 <a class="header-anchor" href="#v20-1" aria-label="Permalink to “v20.1”">​</a></h2><ul><li>[MagiskSU] Support component name agnostic communication (for stub APK)</li><li>[MagiskBoot] Set proper <code>header_size</code> in boot image headers (fix vbmeta error on Samsung devices)</li><li>[MagiskHide] Scan zygote multiple times</li><li>[MagiskInit] Support recovery images without /sbin/recovery binary. This will fix some A/B devices unable to boot to recovery after flashing Magisk</li><li>[General] Move acct to prevent daemon being killed</li><li>[General] Make sure &quot;--remove-modules&quot; will execute uninstall.sh after removal</li></ul><h2 id="v20-0" tabindex="-1">v20.0 <a class="header-anchor" href="#v20-0" aria-label="Permalink to “v20.0”">​</a></h2><ul><li>[MagiskBoot] Support inject/modify <code>mnt_point</code> value in DTB fstab</li><li>[MagiskBoot] Support patching QCDT</li><li>[MagiskBoot] Support patching DTBH</li><li>[MagiskBoot] Support patching PXA-DT</li><li>[MagiskInit] [2SI] Support non A/B setup (Android 10)</li><li>[MagiskHide] Fix bug that reject process names with &quot;:&quot;</li><li>[MagicMount] Fix a bug that cause /product mirror not created</li></ul><h2 id="v19-4" tabindex="-1">v19.4 <a class="header-anchor" href="#v19-4" aria-label="Permalink to “v19.4”">​</a></h2><ul><li>[MagiskInit] [SAR] Boot system-as-root devices with system mounted as /</li><li>[MagiskInit] [2SI] Support 2-stage-init for A/B devices (Pixel 3 Android 10)</li><li>[MagiskInit] [initramfs] Delay sbin overlay creation to post-fs-data</li><li>[MagiskInit] [SARCompat] Old system-as-root implementation is deprecated, no more future changes</li><li>[MagiskInit] Add overlay.d support for root directory overlay for new system-as-root implementation</li><li>[MagiskSU] Unblock all signals in root shells (fix bash on Android)</li><li>[MagicMount] Support replacing files in /product</li><li>[MagiskHide] Support Android 10&#39;s Zygote blastula pool</li><li>[MagiskHide] All random strings now also have random length</li><li>[MagiskBoot] Allow no recompression for ramdisk.cpio</li><li>[MagiskBoot] Support some weird Huawei boot images</li><li>[General] Add new <code>--remove-modules</code> command to remove modules without root in ADB shell</li><li>[General] Support Android 10 new APEX libraries (Project Mainline)</li></ul><h2 id="v19-3" tabindex="-1">v19.3 <a class="header-anchor" href="#v19-3" aria-label="Permalink to “v19.3”">​</a></h2><ul><li>[MagiskHide] Hugely improve process monitor implementation, hopefully should no longer cause 100% CPU and daemon crashes</li><li>[MagiskInit] Wait for partitions to be ready for early mount, should fix bootloops on a handful of devices</li><li>[MagiskInit] Support EROFS used in EMUI 9.1</li><li>[MagiskSU] Properly implement mount namespace isolation</li><li>[MagiskBoot] Proper checksum calculation for header v2</li></ul><h2 id="v19-2" tabindex="-1">v19.2 <a class="header-anchor" href="#v19-2" aria-label="Permalink to “v19.2”">​</a></h2><ul><li>[General] Fix uninstaller</li><li>[General] Fix bootloops on some devices with tmpfs mounting to /data</li><li>[MagiskInit] Add Kirin hi6250 support</li><li>[MagiskSU] Stop claiming device focus for su logging/notify if feasible. This fix issues with users locking Magisk Manager with app lock, and prevent video apps get messed up when an app is requesting root in the background.</li></ul><h2 id="v19-1" tabindex="-1">v19.1 <a class="header-anchor" href="#v19-1" aria-label="Permalink to “v19.1”">​</a></h2><ul><li>[General] Support recovery based Magisk</li><li>[General] Support Android Q Beta 2</li><li>[MagiskInit] New sbin overlay setup process for better compatibility</li><li>[MagiskInit] Allow long pressing volume up to boot to recovery in recovery mode</li><li>[MagicMount] Use proper system_root mirror</li><li>[MagicMount] Use self created device nodes for mirrors</li><li>[MagicMount] Do not allow adding new files/folders in partition root folder (e.g. /system or /vendor)</li></ul><h2 id="v19-0" tabindex="-1">v19.0 <a class="header-anchor" href="#v19-0" aria-label="Permalink to “v19.0”">​</a></h2><ul><li>[General] Remove usage of magisk.img</li><li>[General] Add 64 bit magisk binary for native 64 bit support</li><li>[General] Support A only system-as-root devices that released with Android 9.0</li><li>[General] Support non EXT4 system and vendor partitions</li><li>[MagiskHide] Use Zygote ptracing for monitoring new processes</li><li>[MagiskHide] Targets are now per-application component</li><li>[MagiskInit] Support Android Q (no logical partition support yet!)</li><li>[MagiskPolicy] Support Android Q new split sepolicy setup</li><li>[MagiskInit] Move sbin overlay creation from main daemon post-fs-data to early-init</li><li>[General] Service scripts now run in parallel</li><li>[MagiskInit] Directly inject magisk services to init.rc</li><li>[General] Use lzma2 compressed ramdisk in extreme conditions</li><li>[MagicMount] Clone attributes from original file if exists</li><li>[MagiskSU] Use <code>ACTION_REBOOT</code> intent to workaround some OEM broadcast restrictions</li><li>[General] Use <code>skip_mount</code> instead of <code>auto_mount</code>: from opt-in to opt-out</li></ul><h2 id="v18-1" tabindex="-1">v18.1 <a class="header-anchor" href="#v18-1" aria-label="Permalink to “v18.1”">​</a></h2><ul><li>[General] Support EMUI 9.0</li><li>[General] Support Kirin 960 devices</li><li>[General] Support down to Android 4.2</li><li>[General] Major code base modernization under-the-hood</li></ul><h2 id="v18-0" tabindex="-1">v18.0 <a class="header-anchor" href="#v18-0" aria-label="Permalink to “v18.0”">​</a></h2><ul><li>[General] Migrate all code base to C++</li><li>[General] Modify database natively instead of going through Magisk Manager</li><li>[General] Deprecate path /sbin/.core, please start using /sbin/.magisk</li><li>[General] Boot scripts are moved from <code>&lt;magisk_img&gt;/.core/&lt;stage&gt;.d</code> to <code>/data/adb/&lt;stage&gt;.d</code></li><li>[General] Remove native systemless hosts (Magisk Manager is updated with a built-in systemless hosts module)</li><li>[General] Allow module post-fs-data.sh scripts to disable/remove modules</li><li>[MagiskHide] Use component names instead of process names as targets</li><li>[MagiskHide] Add procfs protection on SDK 24+ (Nougat)</li><li>[MagiskHide] Remove the folder /.backup to prevent detection</li><li>[MagiskHide] Hide list is now stored in database instead of raw textfile in images</li><li>[MagiskHide] Add &quot;--status&quot; option to CLI</li><li>[MagiskHide] Stop unmounting non-custom related mount points</li><li>[MagiskSU] Add <code>FLAG_INCLUDE_STOPPED_PACKAGES</code> in broadcasts to force wake Magisk Manager</li><li>[MagiskSU] Fix a bug causing SIGWINCH not properly detected</li><li>[MagiskPolicy] Support new av rules: type_change, type_member</li><li>[MagiskPolicy] Remove all AUDITDENY rules after patching sepolicy to log all denies for debugging</li><li>[MagiskBoot] Properly support extra_cmdline in boot headers</li><li>[MagiskBoot] Try to repair broken v1 boot image headers</li><li>[MagiskBoot] Add new CPIO command: &quot;exists&quot;</li></ul><h2 id="v17-3" tabindex="-1">v17.3 <a class="header-anchor" href="#v17-3" aria-label="Permalink to “v17.3”">​</a></h2><ul><li>[MagiskBoot] Support boot image header v1 (Pixel 3)</li><li>[MagiskSU] No more linked lists for caching <code>su_info</code></li><li>[MagiskSU] Parse command-lines in client side and send only options to daemon</li><li>[MagiskSU] Early ACK to prevent client freezes and early denies</li><li>[Daemon] Prevent bootloops in situations where /data is mounted twice</li><li>[Daemon] Prevent logcat failures when /system/bin is magic mounting, could cause MagiskHide to fail</li><li>[Scripts] Switch hexpatch to remove Samsung Defex to a more general pattern</li><li>[Scripts] Update data encryption detection for better custom recovery support</li></ul><h2 id="v17-2" tabindex="-1">v17.2 <a class="header-anchor" href="#v17-2" aria-label="Permalink to “v17.2”">​</a></h2><ul><li>[ResetProp] Update to AOSP upstream to support serialized system properties</li><li>[MagiskInit] Randomize Magisk service names to prevent detection (e.g. FGO)</li><li>[MagiskSU] New communication scheme to communicate with Magisk Manager</li></ul><h2 id="v17-0-17-1" tabindex="-1">v17.0/17.1 <a class="header-anchor" href="#v17-0-17-1" aria-label="Permalink to “v17.0/17.1”">​</a></h2><ul><li>[General] Bring back install to inactive slot for OTAs on A/B devices</li><li>[Script] Remove system based root in addon.d</li><li>[Script] Add proper addon.d-v2 for preserving Magisk on custom ROMs on A/B devices</li><li>[Script] Enable KEEPVERITY when the device is using system_root_image</li><li>[Script] Add hexpatch to remove Samsung defex in new Oreo kernels</li><li>[Daemon] Support non ext4 filesystems for mirrors (system/vendor)</li><li>[MagiskSU] Make pts sockets always run in dev_pts secontext, providing all terminal emulator root shell the same power as adb shells</li><li>[MagiskHide] Kill all processes with same UID of the target to workaround OOS embryo optimization</li><li>[MagiskInit] Move all sepolicy patches pre-init to prevent Pixel 2 (XL) boot service breakdown</li></ul><h2 id="v16-7" tabindex="-1">v16.7 <a class="header-anchor" href="#v16-7" aria-label="Permalink to “v16.7”">​</a></h2><ul><li>[Scripts] Fix boot image patching errors on Android P (workaround the strengthened seccomp)</li><li>[MagiskHide] Support hardlink based ns proc mnt (old kernel support)</li><li>[Daemon] Fix permission of /dev/null after logcat commands, fix ADB on EMUI</li><li>[Daemon] Log fatal errors only on debug builds</li><li>[MagiskInit] Detect early mount partname from fstab in device tree</li></ul><h2 id="v16-6" tabindex="-1">v16.6 <a class="header-anchor" href="#v16-6" aria-label="Permalink to “v16.6”">​</a></h2><ul><li>[General] Add wrapper script to overcome weird <code>LD_XXX</code> flags set in apps</li><li>[General] Prevent bootloop when flashing Magisk after full wipe on FBE devices</li><li>[Scripts] Support patching DTB placed in extra sections in boot images (Samsung S9/S9+)</li><li>[Scripts] Add support for addon.d-v2 (untested)</li><li>[Scripts] Fix custom recovery console output in addon.d</li><li>[Scripts] Fallback to parsing sysfs for detecting block devices</li><li>[Daemon] Check whether a valid Magisk Manager is installed on boot, if not, install stub APK embedded in magiskinit</li><li>[Daemon] Check whether Magisk Manager is repackaged (hidden), and prevent malware from hijacking com.topjohnwu.magisk</li><li>[Daemon] Introduce new daemon: magisklogd, a dedicated daemon to handle all logcat related monitoring</li><li>[Daemon] Replace old invincible mode with handshake between magiskd and magisklogd, one will respawn the other if disconnected</li><li>[Daemon] Support GSI adbd bind mounting</li><li>[MagiskInit] Support detecting block names in upper case (Samsung)</li><li>[MagiskBoot] Check DTB headers to prevent false detections within kernel binary</li><li>[MagiskHide] Compare mount namespace with PPID to make sure the namespace is actually separated, fix root loss</li><li>[MagiskSU] Simplify <code>su_info</code> caching system, should use less resources and computing power</li><li>[MagiskSU] Reduce the amount of broadcasting to Magisk Manager</li><li>[ImgTool] Separate all ext4 image related operations to a new applet called &quot;imgtool&quot;</li><li>[ImgTool] Use precise free space calculation methods</li><li>[ImgTool] Use our own set of loop devices hidden along side with sbin tmpfs overlay. This not only eliminates another possible detection method, but also fixes apps that mount OBB files as loop devices (huge thanks to dev of Pzizz for reporting this issue)</li></ul><h2 id="v16-4" tabindex="-1">v16.4 <a class="header-anchor" href="#v16-4" aria-label="Permalink to “v16.4”">​</a></h2><ul><li>[Daemon] Directly check logcat command instead of detecting logd, should fix logging and MagiskHide on several Samsung devices</li><li>[Daemon] Fix startup Magisk Manager APK installation on Android P</li><li>[MagiskPolicy] Switch from AOSP u:r:su:s0 to u:r:magisk:s0 to prevent conflicts</li><li>[MagiskPolicy] Remove unnecessary sepolicy rules to reduce security penalty</li><li>[Daemon] Massive re-design /sbin tmpfs overlay and daemon start up</li><li>[MagiskInit] Remove <code>magiskinit_daemon</code>, the actual magisk daemon (magiskd) shall handle everything itself</li><li>[Daemon] Remove post-fs stage as it is very limited and also will not work on A/B devices; replaced with simple mount in post-fs-data, which will run ASAP even before the daemon is started</li><li>[General] Remove all 64-bit binaries as there is no point in using them; all binaries are now 32-bit only. Some weirdly implemented root apps might break (e.g. Tasker, already reported to the developer), but it is not my fault 😃</li><li>[resetprop] Add Protobuf encode/decode to support manipulating persist properties on Android P</li><li>[MagiskHide] Include app sub-services as hiding targets. This might significantly increase the amount of apps that could be properly hidden</li></ul><h2 id="v16-3" tabindex="-1">v16.3 <a class="header-anchor" href="#v16-3" aria-label="Permalink to “v16.3”">​</a></h2><ul><li>[General] Remove symlinks used for backwards compatibility</li><li>[MagiskBoot] Fix a small size calculation bug</li></ul><h2 id="v16-2" tabindex="-1">v16.2 <a class="header-anchor" href="#v16-2" aria-label="Permalink to “v16.2”">​</a></h2><ul><li>[General] Force use system binaries in handling ext4 images (fix module installation on Android P)</li><li>[MagiskHide] Change property state to disable if logd is disabled</li></ul><h2 id="v16-1" tabindex="-1">v16.1 <a class="header-anchor" href="#v16-1" aria-label="Permalink to “v16.1”">​</a></h2><ul><li>[MagiskBoot] Fix MTK boot image packaging</li><li>[MagiskBoot] Add more Nook/Acclaim headers support</li><li>[MagiskBoot] Support unpacking DTB with empty kernel image</li><li>[MagiskBoot] Update high compression mode detection logic</li><li>[Daemon] Support new mke2fs tool on Android P</li><li>[resetprop] Support Android P new property context files</li><li>[MagiskPolicy] Add new rules for Android P</li></ul><h2 id="v16-0" tabindex="-1">v16.0 <a class="header-anchor" href="#v16-0" aria-label="Permalink to “v16.0”">​</a></h2><ul><li>[MagiskInit] Support non <code>skip_initramfs</code> devices with slot suffix (Huawei Treble)</li><li>[MagiskPolicy] Add rules for Magisk Manager</li><li>[Compiler] Workaround an NDK compiler bug that causes bootloops</li></ul><h2 id="v15-4" tabindex="-1">v15.4 <a class="header-anchor" href="#v15-4" aria-label="Permalink to “v15.4”">​</a></h2><ul><li>[MagiskBoot] Support Samsung PXA, DHTB header images</li><li>[MagiskBoot] Support ASUS blob images</li><li>[MagiskBoot] Support Nook Green Loader images</li><li>[MagiskBoot] Support pure ramdisk images</li><li>[MagiskInit] Prevent OnePlus angela <code>sepolicy_debug</code> from loading</li><li>[MagiskInit] Obfuscate Magisk socket entry to prevent detection and security</li><li>[Daemon] Fix subfolders in /sbin shadowed by overlay</li><li>[Daemon] Obfuscate binary names to prevent naive detections</li><li>[Daemon] Check logd before force trying to start logcat in a loop</li></ul><h2 id="v15-3" tabindex="-1">v15.3 <a class="header-anchor" href="#v15-3" aria-label="Permalink to “v15.3”">​</a></h2><ul><li>[Daemon] Fix the bug that only one script would be executed in post-fs-data.d/service.d</li><li>[Daemon] Add <code>MS_SILENT</code> flag when mounting, should fix some devices that cannot mount magisk.img</li><li>[MagiskBoot] Fix potential segmentation fault when patching ramdisk, should fix some installation failures</li></ul><h2 id="v15-2" tabindex="-1">v15.2 <a class="header-anchor" href="#v15-2" aria-label="Permalink to “v15.2”">​</a></h2><ul><li>[MagiskBoot] Fix dtb verity patches, should fix dm-verity bootloops on newer devices placing fstabs in dtb</li><li>[MagiskPolicy] Add new rules for proper Samsung support, should fix MagiskHide</li><li>[MagiskInit] Support non <code>skip_initramfs</code> devices using split sepolicies (e.g. Zenfone 4 Oreo)</li><li>[Daemon] Use specific logcat buffers, some devices does not support all log buffers</li><li>[scripts] Update scripts to double check whether boot slot is available, some devices set a boot slot without A/B partitions</li></ul><h2 id="v15-1" tabindex="-1">v15.1 <a class="header-anchor" href="#v15-1" aria-label="Permalink to “v15.1”">​</a></h2><ul><li>[MagiskBoot] Fix faulty code in ramdisk patches which causes bootloops in some config and fstab format combos</li></ul><h2 id="v15-0" tabindex="-1">v15.0 <a class="header-anchor" href="#v15-0" aria-label="Permalink to “v15.0”">​</a></h2><ul><li>[Daemon] Fix the bug that Magisk cannot properly detect /data encryption state</li><li>[Daemon] Add merging <code>/cache/magisk.img</code> and <code>/data/adb/magisk_merge.img</code> support</li><li>[Daemon] Update to upstream libsepol to support cutting edge split policy custom ROM cil compilations</li></ul><h2 id="v14-6-1468" tabindex="-1">v14.6 (1468) <a class="header-anchor" href="#v14-6-1468" aria-label="Permalink to “v14.6 (1468)”">​</a></h2><ul><li>[General] Move all files into a safe location: /data/adb</li><li>[Daemon] New invincible implementation: use <code>magiskinit_daemon</code> to monitor sockets</li><li>[Daemon] Rewrite logcat monitor to be more efficient</li><li>[Daemon] Fix a bug where logcat monitor may spawn infinite logcat processes</li><li>[MagiskSU] Update su to work the same as proper Linux implementation: Initialize window size; all environment variables will be migrated (except HOME, SHELL, USER, LOGNAME, these will be set accordingly), &quot;--preserve-environment&quot; option will preserve all variables, including those four exceptions. Check the Linux su manpage for more info</li><li>[MagiskBoot] Massive refactor, rewrite all cpio operations and CLI</li><li>[MagiskInit][magiskboot] Support ramdisk high compression mode</li></ul><h2 id="v14-5-1456" tabindex="-1">v14.5 (1456) <a class="header-anchor" href="#v14-5-1456" aria-label="Permalink to “v14.5 (1456)”">​</a></h2><ul><li>[Magiskinit] Fix bootloop issues on several devices</li><li>[misc] Build binaries with NDK r10e, should get rid of the nasty linker warning when executing magisk</li></ul><h2 id="v14-5-1455" tabindex="-1">v14.5 (1455) <a class="header-anchor" href="#v14-5-1455" aria-label="Permalink to “v14.5 (1455)”">​</a></h2><ul><li>[Daemon] Moved internal path to /sbin/.core, new image mountpoint is /sbin/.core/img</li><li>[MagiskSU] Support switching package name, used when Magisk Manager is hidden</li><li>[MagiskHide] Add temporary /magisk removal</li><li>[MagiskHide] All changes above contributes to hiding from nasty apps like FGO and several banking apps</li><li>[Magiskinit] Use magiskinit for all devices (dynamic initramfs)</li><li>[Magiskinit] Fix Xiaomi A1 support</li><li>[Magiskinit] Add Pixel 2 (XL) support</li><li>[Magiskboot] Add support to remove avb-verity in dtbo.img</li><li>[Magiskboot] Fix typo in handling MTK boot image headers</li><li>[script] Along with updates in Magisk Manager, add support to sign boot images (AVB 1.0)</li><li>[script] Add dtbo.img backup and restore support</li><li>[misc] Many small adjustments to properly support old platforms like Android 5.0</li></ul><h2 id="v14-3-1437" tabindex="-1">v14.3 (1437) <a class="header-anchor" href="#v14-3-1437" aria-label="Permalink to “v14.3 (1437)”">​</a></h2><ul><li>[MagiskBoot] Fix Pixel C installation</li><li>[MagiskBoot] Handle special <code>lz4_legacy</code> format properly, should fix all LG devices</li><li>[Daemon] New universal logcat monitor is added, support plug-and-play to worker threads</li><li>[Daemon] Invincible mode: daemon will be restarted by init, everything should seamlessly through daemon restarts</li><li>[Daemon] Add new restorecon action, will go through and fix all Magisk files with selinux unlabeled to <code>system_file</code> context</li><li>[Daemon] Add brute-force image resizing mode, should prevent the notorious Samsung crappy resize2fs from affecting the result</li><li>[resetprop] Add new &quot;-p&quot; flag, used to toggle whether alter/access the actual persist storage for persist props</li></ul><h2 id="v14-2" tabindex="-1">v14.2 <a class="header-anchor" href="#v14-2" aria-label="Permalink to “v14.2”">​</a></h2><ul><li>[MagicMount] Clone attributes to tmpfs mountpoint, should fix massive module breakage</li></ul><h2 id="v14-1" tabindex="-1">v14.1 <a class="header-anchor" href="#v14-1" aria-label="Permalink to “v14.1”">​</a></h2><ul><li>[MagiskInit] Introduce a new init binary to support <code>skip_initramfs</code> devices (Pixel family)</li><li>[script] Fix typo in update-binary for x86 devices</li><li>[script] Fix stock boot image backup not moved to proper location</li><li>[script] Add functions to support A/B slot and <code>skip_initramfs</code> devices</li><li>[script] Detect Meizu boot blocks</li><li>[MagiskBoot] Add decompress zImage support</li><li>[MagiskBoot] Support extracting dtb appended to zImage block</li><li>[MagiskBoot] Support patching fstab within dtb</li><li>[Daemon/MagiskSU] Proper file based encryption support</li><li>[Daemon] Create core folders if not exist</li><li>[resetprop] Fix a bug which delete props won&#39;t remove persist props not in memory</li><li>[MagicMount] Remove usage of dummy folder, directly mount tmpfs and construct file structure skeleton in place</li></ul><h2 id="v14-0" tabindex="-1">v14.0 <a class="header-anchor" href="#v14-0" aria-label="Permalink to “v14.0”">​</a></h2><ul><li>[script] Simplify installation scripts</li><li>[script] Fix a bug causing backing up and restoring stock boot images failure</li><li>[script] Installation and uninstallation will migrate old or broken stock boot image backups to proper format</li><li>[script] Fix an issue with selabel setting in <code>util_functions.sh</code> on Lollipop</li><li>[rc script] Enable logd in post-fs to start logging as early as possible</li><li>[MagiskHide] magisk.img mounted is no longer a requirement Devices with issues mounting magisk.img can now run in proper core-only mode</li><li>[MagiskBoot] Add native function to extract stock SHA1 from ramdisk</li><li>[b64xz] New tool to extract compressed and encoded binary dumps in shell script</li><li>[busybox] Add busybox to Magisk source, and embed multi-arch busybox binary into update-binary shell script</li><li>[busybox] Busybox is added into PATH for all boot scripts (post-fs-data.d, service.d, and all module scripts)</li><li>[MagiskSU] Fully fix multiuser issues</li><li>[Magic Mount] Fix a typo in cloning attributes</li><li>[Daemon] Fix the daemon crashing when boot scripts opens a subshell</li><li>[Daemon] Adjustments to prevent stock Samsung kernel restrictions on exec system calls for binaries started from /data</li><li>[Daemon] Workaround on Samsung device with weird fork behaviors</li></ul><h2 id="v13-3" tabindex="-1">v13.3 <a class="header-anchor" href="#v13-3" aria-label="Permalink to “v13.3”">​</a></h2><ul><li>[MagiskHide] Update to bypass Google CTS (2017.7.17)</li><li>[resetprop] Properly support removing persist props</li><li>[uninstaller] Remove Magisk Manager and persist props</li></ul><h2 id="v13-2" tabindex="-1">v13.2 <a class="header-anchor" href="#v13-2" aria-label="Permalink to “v13.2”">​</a></h2><ul><li>[magiskpolicy] Fix magiskpolicy segfault on old Android versions, should fix tons of older devices that couldn&#39;t use v13.1</li><li>[MagiskHide] Set proper selinux context while re-linking /sbin to hide Magisk, should potentially fix many issues</li><li>[MagiskBoot] Change lzma compression encoder flag from <code>LZMA_CHECK_CRC64</code> to <code>LZMA_CHECK_CRC32</code>, kernel only supports latter</li><li>[General] Core-only mode now properly mounts systemless hosts and magiskhide</li></ul><h2 id="v13-1" tabindex="-1">v13.1 <a class="header-anchor" href="#v13-1" aria-label="Permalink to “v13.1”">​</a></h2><ul><li>[General] Merge MagiskSU, magiskhide, resetprop, magiskpolicy into one binary</li><li>[General] Add Android O support (tested on DP3)</li><li>[General] Dynamic link libselinux.so, libsqlite.so from system to greatly reduce binary size</li><li>[General] Remove bundled busybox because it causes a lot of issues</li><li>[General] Unlock all block devices for read-write support instead of emmc only (just figured not all devices uses emmc lol)</li><li>[Scripts] Run all ext4 image operations through magisk binary in flash scripts</li><li>[Scripts] Updated scripts to use magisk native commands to increase compatibility</li><li>[Scripts] Add addon.d survival support</li><li>[Scripts] Introduce <code>util_functions.sh</code>, used as a global shell script function source for all kinds of installation</li><li>[MagiskBoot] Moved boot patch logic into magiskboot binary</li><li>[MagiskSU] Does not fork new process for each request, add new threads instead</li><li>[MagiskSU] Added multiuser support</li><li>[MagiskSU] Introduce new timeout queue mechanism, prevent performance hit with poorly written su apps</li><li>[MagiskSU] Multiple settings moved from prop detection to database</li><li>[MagiskSU] Add namespace mode option support</li><li>[MagiskSU] Add master-mount option</li><li>[resetprop] Updated to latest AOSP upstream, support props from 5.0 to Android O</li><li>[resetprop] Renamed all functions to prevent calling functions from external libc</li><li>[magiskpolicy] Updated libsepol from official SELinux repo</li><li>[magiskpolicy] Added xperm patching support (in order to make Android O work properly)</li><li>[magiskpolicy] Updated rules for Android O, and Liveboot support</li><li>[MagiskHide] Remove pseudo permissive mode, directly hide permissive status instead</li><li>[MagiskHide] Remove unreliable list file monitor, change to daemon request mode</li><li>[MagiskHide] MagiskHide is now enabled by default</li><li>[MagiskHide] Update unmount policies, passes CTS in SafetyNet!</li><li>[MagiskHide] Add more props for hiding</li><li>[MagiskHide] Remove background magiskhide daemon, spawn short life process for unmounting purpose</li><li>[Magic Mount] Ditched shell script based mounting, use proper C program to parse and mount files. Speed is SIGNIFICANTLY improved</li></ul><h2 id="v12-0" tabindex="-1">v12.0 <a class="header-anchor" href="#v12-0" aria-label="Permalink to “v12.0”">​</a></h2><ul><li>[General] Move most binaries into magisk.img (Samsung cannot run su daemon in /data)</li><li>[General] Move sepolicy live patch to <code>late_start</code> service This shall fix the long boot times, especially on Samsung devices</li><li>[General] Add Samsung RKP hexpatch back, should now work on Samsung stock kernels</li><li>[General] Fix installation with SuperSU</li><li>[MagiskHide] Support other logcat <code>am_proc_start</code> patterns</li><li>[MagiskHide] Change /sys/fs/selinux/enforce(policy) permissions if required Samsung devices cannot switch selinux states, if running on permissive custom kernel, the users will stuck at permissive If this scenario is detected, change permissions to hide the permissive state, leads to SafetyNet passes</li><li>[MagiskHide] Add built in prop rules to fake KNOX status Samsung apps requiring KNOX status to be 0x0 should now work (Samsung Pay not tested)</li><li>[MagiskHide] Remove all ro.build props, since they cause more issues than they benefit...</li><li>[MagiskBoot] Add lz4 legacy format support (most linux kernel using lz4 for compression is using this)</li><li>[MagiskBoot] Fix MTK kernels with MTK headers</li></ul><h2 id="v11-5-11-6" tabindex="-1">v11.5/11.6 <a class="header-anchor" href="#v11-5-11-6" aria-label="Permalink to “v11.5/11.6”">​</a></h2><ul><li>[Magic Mount] Fix mounting issues with devices that have separate /vendor partitions</li><li>[MagiskBoot] Whole new boot image patching tool, please check release note for more info</li><li>[magiskpolicy] Rename sepolicy-inject to magiskpolicy</li><li>[magiskpolicy] Update a rule to allow chcon everything properly</li><li>[MagiskHide] Prevent multirom crashes</li><li>[MagiskHide] Add patches for ro.debuggable, ro.secure, ro.build.type, ro.build.tags, ro.build.selinux</li><li>[MagiskHide] Change /sys/fs/selinux/enforce, /sys/fs/selinux/policy permissions for Samsung compatibility</li><li>[MagiskSU] Fix read-only partition mounting issues</li><li>[MagiskSU] Disable -cn option, the option will do nothing, preserved for compatibility</li></ul><h2 id="v11-1" tabindex="-1">v11.1 <a class="header-anchor" href="#v11-1" aria-label="Permalink to “v11.1”">​</a></h2><ul><li>[sepolicy-inject] Add missing messages</li><li>[magiskhide] Start MagiskHide with scripts</li></ul><h2 id="v11-0" tabindex="-1">v11.0 <a class="header-anchor" href="#v11-0" aria-label="Permalink to “v11.0”">​</a></h2><ul><li>[Magic Mount] Support replacing symlinks. Symlinks cannot be a target of a bind mounted, so they are treated the same as new files</li><li>[Magic Mount] Fix the issue when file/folder name contains spaces</li><li>[BusyBox] Updated to v1.26.2. Should fix the black screen issues of FlashFire</li><li>[resetprop] Support reading prop files that contains spaces in prop values</li><li>[MagiskSU] Adapt communication to Magisk Manager; stripped out unused data transfer</li><li>[MagiskSU] Implement SuperUser access option (Disable, APP only, ADB Only, APP &amp; ADB) phh Superuser app has this option but the feature isn&#39;t implemented within the su binary</li><li>[MagiskSU] Fixed all issues with su -c &quot;commands&quot; (run commands with root) This feature is supposed to only allow one single option, but apparently adb shell su -c &quot;command&quot; doesn&#39;t work this way, and plenty of root apps don&#39;t follow the rule. The su binary will now consider everything after -c as a part of the command.</li><li>[MagiskSU] Removed legacy context hack for TiBack, what it currently does is slowing down the invocation</li><li>[MagiskSU] Preserve the current working directory after invoking su Previously phh superuser will change the path to /data/data after obtaining root shell. It will now stay in the same directory where you called su</li><li>[MagiskSU] Daemon now also runs in u:r:su:s0 context</li><li>[MagiskSU] Removed an unnecessary fork, reduce running processes and speed up the invocation</li><li>[MagiskSU] Add -cn option to the binary Not sure if this is still relevant, and also not sure if implemented correctly, but hey it&#39;s here</li><li>[sepolicy-inject] Complete re-write the command-line options, now nearly matches supolicy syntax</li><li>[sepolicy-inject] Support all matching mode for nearly every action (makes pseudo enforced possible)</li><li>[sepolicy-inject] Fixed an ancient bug that allocated memory isn&#39;t reset</li><li>[uninstaller] Now works as a independent script that can be executed at boot Fully support recovery with no /data access, Magisk uninstallation with Magisk Manager</li><li>[Addition] Busybox, MagiskHide, hosts settings can now be applied instantly; no reboots required</li><li>[Addition] Add post-fs-data.d and service.d</li><li>[Addition] Add option to disable Magisk (MagiskSU will still be started)</li></ul><h2 id="v10-2" tabindex="-1">v10.2 <a class="header-anchor" href="#v10-2" aria-label="Permalink to “v10.2”">​</a></h2><ul><li>[Magic Mount] Remove apps/priv-app from whitelist, should fix all crashes</li><li>[phh] Fix binary out-of-date issue</li><li>[scripts] Fix root disappear issue when upgrading within Magisk Manager</li></ul><h2 id="v10" tabindex="-1">v10 <a class="header-anchor" href="#v10" aria-label="Permalink to “v10”">​</a></h2><ul><li>[Magic Mount] Use a new way to mount system (vendor) mirrors</li><li>[Magic Mount] Use universal way to deal with /vendor, handle both separate partition or not</li><li>[Magic Mount] Adding <strong>anything to any place</strong> is now officially supported (including /system root and /vendor root)</li><li>[Magic Mount] Use symlinks for mirroring back if possible, reduce bind mounts for adding files</li><li>[Magisk Hide] Check init namespace, zygote namespace to prevent Magic Mount breakage (a.k.a root loss)</li><li>[Magisk Hide] Send SIGSTOP to pause target process ASAP to prevent crashing if unmounting too late</li><li>[Magisk Hide] Hiding should work under any conditions, including adding libs and /system root etc.</li><li>[phh] Root the device if no proper root detected</li><li>[phh] Move <code>/sbin</code> to <code>/sbin_orig</code> and link back, fix Samsung no-suid issue</li><li>[scripts] Improve SuperSU integration, now uses sukernel to patch ramdisk, support SuperSU built in ramdisk restore</li><li>[template] Add PROPFILE option to load system.prop</li></ul><h2 id="v9" tabindex="-1">v9 <a class="header-anchor" href="#v9" aria-label="Permalink to “v9”">​</a></h2><ul><li><strong>[API Change] Remove the interface for post-fs modules</strong></li><li>[resetprop] New tool &quot;resetprop&quot; is added to Magisk to replace most post-fs modules&#39; functionality</li><li>[resetprop] Magisk will now patch &quot;ro.boot.verifiedbootstate&quot;, &quot;ro.boot.flash.locked&quot;, &quot;ro.boot.veritymode&quot; to bypass Safety Net</li><li>[Magic Mount] Move dummy skeleton / mirror / mountinfo filesystem tree to tmpfs</li><li>[Magic Mount] Rewritten dummy cloning mechanism from scratch, will result in minimal bind mounts, minimal file traversal, eliminate all possible issues that might happen in extreme cases</li><li>[Magic Mount] Adding new items to /system/bin, /system/vendor, /system/lib(64) is properly supported (devices with separate vendor partition is not supported yet)</li><li>[Magisk Hide] Rewritten from scratch, now run in daemon mode, proper list monitoring, proper mount detection, and maybe more.....</li><li>[Boot Image] Add support for Motorola boot image dtb, it shall now unpack correctly</li><li>[Uninstaller] Add removal of SuperSU custom patch script</li></ul><h2 id="v8" tabindex="-1">v8 <a class="header-anchor" href="#v8" aria-label="Permalink to “v8”">​</a></h2><ul><li>Add Magisk Hide to bypass SafetyNet</li><li>Improve SuperSU integration: no longer changes the SuperSU PATH</li><li>Support rc script entry points not located in init.rc</li></ul><h2 id="v7" tabindex="-1">v7 <a class="header-anchor" href="#v7" aria-label="Permalink to “v7”">​</a></h2><ul><li>Fully open source</li><li>Remove supolicy dependency, use my own sepolicy-injection</li><li>Run everything in its own selinux domain, should fix all selinux issues</li><li>Add Note 7 stock kernel hex patches</li><li>Add support to install Magisk in Magisk Manager</li><li>Add support for image merging for module flashing in Magisk Manager</li><li>Add root helpers for SuperSU auto module-ize and auto upgrading legacy phh superuser</li><li>New paths to toggle busybox, and support all root solutions</li><li>Remove root management API; both SuperSU and phh has their own superior solutions</li></ul><h2 id="v6" tabindex="-1">v6 <a class="header-anchor" href="#v6" aria-label="Permalink to “v6”">​</a></h2><ul><li>Fixed the algorithm for adding new files and dummy system</li><li>Updated the module template with a default permission, since people tend to forget them 😃</li></ul><h2 id="v5" tabindex="-1">v5 <a class="header-anchor" href="#v5" aria-label="Permalink to “v5”">​</a></h2><ul><li>Hotfix for older Android versions (detect policy before patching)</li><li>Update uninstaller to NOT uninstall Magisk Manager, since it cause problems</li></ul><h2 id="v4" tabindex="-1">v4 <a class="header-anchor" href="#v4" aria-label="Permalink to “v4”">​</a></h2><ul><li>Important: Uninstall v1 - v3 Magisk before upgrading with the uninstaller in the OP!!</li><li>Massive Rewrite Magisk Interface API! All previous mods are NOT compatible! Please download the latest version of the mods you use (root/xposed)</li><li>Mods are now installed independently in their own subfolder. This paves the way for future Magisk Manager versions to manage mods, <strong>just like how Xposed Modules are handled</strong></li><li>Support small boot partition devices (Huawei devices)</li><li>Use minimal sepolicy patch in boot image for smaller ramdisk size. Live patch policies after bootup</li><li>Include updated open source sepolicy injection tool (source code available), support nearly all SuperSU supolicy tool&#39;s functionality</li></ul><h2 id="v3" tabindex="-1">v3 <a class="header-anchor" href="#v3" aria-label="Permalink to “v3”">​</a></h2><ul><li>Fix bootimg-extract for Exynos Samsung devices (thanks to @phhusson), should fix all Samsung device issues</li><li>Add supolicy back to patch sepolicy (stock Samsung do not accept permissive domain)</li><li>Update sepolicy-injection to patch su domain for Samsung devices to use phh&#39;s root</li><li>Update root disable method, using more aggressive approach</li><li>Use lazy unmount to unmount root from system, should fix some issues with custom roms</li><li>Use the highest possible compression rate for ramdisk, hope to fix some devices with no boot partition space</li><li>Detect boot partition space insufficient, will abort installer instead of breaking your device</li></ul><h2 id="v2" tabindex="-1">v2 <a class="header-anchor" href="#v2" aria-label="Permalink to “v2”">​</a></h2><ul><li>Fix verity patch. It should now work on all devices (might fix some of the unable-to-boot issues)</li><li>All scripts will now run in selinux permissive mode for maximum compatibility (this will <strong>NOT</strong> turn your device to permissive)</li><li>Add Nougat Developer Preview 5 support</li><li>Add systemless host support for AdBlock Apps (enabled by default)</li><li>Add support for new root disable method</li><li>Remove sepolicy patches that uses SuperSU&#39;s supolicy tool; it is now using a minimal set of modifications</li><li>Removed Magisk Manager in Magisk patch, it is now included in Magisk phh&#39;s superuser only</li></ul><h2 id="v1" tabindex="-1">v1 <a class="header-anchor" href="#v1" aria-label="Permalink to “v1”">​</a></h2><ul><li>Initial release</li></ul><h2 id="参考链接" tabindex="-1">参考链接 <a class="header-anchor" href="#参考链接" aria-label="Permalink to “参考链接”">​</a></h2><ul><li><a href="https://topjohnwu.github.io/Magisk/changes.html" target="_blank" rel="noreferrer">Magisk Magisk Changelog</a>（官方）</li></ul>`,193)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};